CREATE TABLE IF NOT EXISTS "release_merge_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "event_key" text NOT NULL, "repository" text NOT NULL, "pull_request_number" integer NOT NULL, "merge_sha" text NOT NULL, "merged_at" timestamp with time zone NOT NULL, "product" text NOT NULL, "app" text NOT NULL, "payload" jsonb NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "release_merge_events_event_key_unique" ON "release_merge_events" ("event_key");
CREATE TABLE IF NOT EXISTS "release_daily_posts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "product" text NOT NULL, "app" text NOT NULL, "local_date" text NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "release_daily_posts_identity_unique" ON "release_daily_posts" ("product", "app", "local_date");
CREATE TABLE IF NOT EXISTS "release_daily_post_entries" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "post_id" uuid NOT NULL REFERENCES "release_daily_posts"("id") ON DELETE cascade, "event_id" uuid NOT NULL REFERENCES "release_merge_events"("id") ON DELETE restrict, "repository" text NOT NULL, "app" text NOT NULL, "pull_request_number" integer NOT NULL, "merge_sha" text NOT NULL, "title" text NOT NULL, "body" text, "url" text, "material" boolean NOT NULL, "audience_eligible" boolean NOT NULL, "payload" jsonb NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE INDEX IF NOT EXISTS "release_daily_post_entries_post_idx" ON "release_daily_post_entries" ("post_id");
CREATE TABLE IF NOT EXISTS "release_daily_post_dismissals" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "post_id" uuid NOT NULL REFERENCES "release_daily_posts"("id") ON DELETE cascade, "user_id" uuid NOT NULL, "dismissed_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "release_daily_post_dismissals_user_post_unique" ON "release_daily_post_dismissals" ("post_id", "user_id");
